topics.body:
// делит и округляет вниз (к меньшему целому): 7 // 2 == 3, а -7 // 2 == -4.

% — остаток от деления: 7 % 3 == 1. Удобно проверять чётность: n % 2 == 0.

** — возведение в степень: 2 ** 10 == 1024. Знак ^ в Python — это побитовое «исключающее или», не степень.

examples.code:
score = 73
if score >= 90:
    print('A')
elif score >= 70:
    print('B')
else:
    print('C')

for ch in 'кот':
    print(ch)
print('готово')

for n in range(10):
    if n == 3:
        break
    print(n)

total = 0
for n in range(6):
    if n % 2 == 0:
        continue
    total += n
print(total)

for n in [3, 5, 7]:
    if n % 2 == 0:
        print('нашли чётное')
        break
else:
    print('все нечётные')

for i in range(1, 3):
    for j in range(1, 3):
        print(i, j)

a = {1, 2, 3}
b = {2, 3, 4}
print(sorted(a | b), sorted(a & b), sorted(a - b), sorted(a ^ b))

ages = {'Ада': 36, 'Алан': 41}
ages['Грейс'] = 85
print(ages['Алан'], len(ages))

prices = {'чай': 3, 'кофе': 5}
for name, price in prices.items():
    print(name, price)
print(prices.get('сок', 0), 'чай' in prices, 3 in prices)

counts = {}
for ch in 'abracadabra':
    counts[ch] = counts.get(ch, 0) + 1
print(counts)
